sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
                        /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
                        /* Optional GlideRecord */ event) {

    var gd = new GlideRecord('sys_user_grmember');
    gd.addQuery('group.name', 'IN', 'IT Refunds Group,Refund HR Resolvers,Kitchen Resolvers Group,Food Refunds Group');
    gd.orderByDesc('sys_updated_on'); // Sort by the latest updated records first
    gd.query();

    if (gd.next()) {
        // Fetch the User, Group Name, and Updated Time fields from the latest updated record
        var lastUpdatedUser = gd.user.getDisplayValue();
        var lastUpdatedTime = gd.sys_updated_on.getDisplayValue();
        var lastUpdatedGroupName = gd.group.name.getDisplayValue();

        // Print the latest updated record's User, Group Name, and Updated Time to the notification
        template.print(
            "Last updated record User: " + lastUpdatedUser + 
            ", Group: " + lastUpdatedGroupName + 
            ", Updated On: " + lastUpdatedTime
        );
    } else {
        // Print a message if no records were found
        template.print("No matching records found.");
    }

}) (current, template, email, email_action, event);
